sys_script_include.script:
var SelectSwiftLinkingSI = Class.create();
SelectSwiftLinkingSI.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getAvailableTrades: function(tranRef, ownBusiness) {

        var trades = [];
        var gr = new GlideRecord('sn_bom_trade');
        gr.addEncodedQuery('sys_class_name=x_hsb11_mss_c_proc_mss_custody_trade^ORsys_class_name=x_hsb11_mss_c_proc_mss_custody_trade_passive');
        gr.addEncodedQuery('u_idLIKE' + tranRef.toString() + '^ref_x_hsb11_mss_c_proc_mss_custody_trade.owning_business=' + ownBusiness + '^NQu_idLIKE' + tranRef.toString() + '^ref_x_hsb11_mss_c_proc_mss_custody_trade_passive.owning_business=' + ownBusiness);
        gr.query();
        while (gr.next()) {

            trades.push(gr.sys_id.toString());

        }

        return 'sys_idIN' + trades;

    },

    type: 'SelectSwiftLinkingSI'
});
